import {renderSpans} from './spans.js?v=9d97c650b6d2';
import {state,currentModel,DEMO} from '../../core/state.js?v=9d97c650b6d2';
import {api,projectQuery} from '../../core/api.js?v=9d97c650b6d2';
import {T,esc,icon,heading,btn,panel,stat,pct,num,badge,modal,select,field,formEnd,closeModal,toast,download,nativeRequired} from '../../core/ui.js?v=9d97c650b6d2';
let selectedBenchmark=null,connections=[];
export async function load(){if(state.workspace.project.can_manage)connections=(await api('studio/connections'+projectQuery())).connections;}
export function render(){const s=state.workspace,m=currentModel(),r=m?.report;if(r?.task==='token_classification')return renderSpans(m);if(!r?.test)return panel(T('Chưa có kết quả','No results yet'),T('Huấn luyện model hoặc chuẩn bị model baseline trước.','Train a model or seed the baseline models first.'));const history=(s.benchmarks||[]).filter(x=>x.report?.local_model_id===m.id),run=history.find(x=>x.id===selectedBenchmark)||history[0],a=run?.report;const local=a?.local||r.test,remote=a?.api||a?.gemini;const keys=a?.label_keys||r.label_keys||['NON_TOXIC','TOXIC'];return heading(T('Đánh giá model & API','Model & API evaluation'),T('Cùng mẫu test, cùng bộ nhãn, kết quả được ghi theo từng lượt chạy.','The same test samples, the same label schema, and separate recorded runs.'),btn(T('Tải báo cáo','Download report'),'evaluation:download','','download')+btn(T('Đánh giá API','Benchmark API'),'evaluation:benchmark','primary','play',s.project.can_manage?'':'disabled'))+`<div class="info-banner mb16">${icon('info',18)}<span>${a?T('Bảng dưới dùng lượt chấm ghép cặp đã chọn, không trộn với test của phiên khác.','The table uses the selected paired run, without mixing test sets from other runs.'):T('Model đã có kết quả đo thật. API chưa được chấm; chưa thể kết luận nhánh nào tốt hơn.','The model has real measured results. The API is unmeasured, so no winner can be concluded.')}</span></div><div class="stats-grid">${stat('Macro-F1',pct(local.macro_f1),esc(m.name),'chart')}${stat('Precision macro',pct(local.precision),T('Trung bình đều theo lớp','Unweighted mean across classes'),'shield')}${stat('Recall macro',pct(local.recall),T('Báo cả lớp hiếm','Includes minority classes'),'eye')}${stat(T('Mẫu test','Test samples'),num(local.n),T('Chỉ số phụ thuộc tập test','Results depend on the test set'),'database')}</div><div class="split-grid"><div class="stack">${panel(T('So sánh các nhánh','Compare prediction branches'),`<div class="table-wrap"><table><thead><tr><th>${T('CHỈ SỐ','METRIC')}</th><th>MODEL</th><th>API</th></tr></thead><tbody>${[['Accuracy','accuracy'],['Precision macro','precision'],['Recall macro','recall'],['Macro-F1','macro_f1']].map(([name,key])=>`<tr><td>${name}</td><td>${pct(local[key])}</td><td>${remote?pct(remote[key]):T('Chưa đo','Unmeasured')}</td></tr>`).join('')}<tr><td>${T('Số mẫu','Samples')}</td><td>${num(local.n)}</td><td>${remote?num(remote.n):'—'}</td></tr><tr><td>${T('Thời gian / mẫu','Latency / sample')}</td><td>${(a?.local_ms??r.mean_prediction_ms)?.toFixed(3)} ms</td><td>${a?(a.api_ms??a.gemini_ms)?.toFixed(1)+' ms':'—'}</td></tr><tr><td>${T('Token API','API tokens')}</td><td>—</td><td>${a?num(a.tokens):'—'}</td></tr><tr><td>${T('Chi phí API ước tính','Estimated API cost')}</td><td>—</td><td>${a?'$'+a.estimated_cost_usd?.toFixed(5):T('Chưa phát sinh','Not incurred')}</td></tr></tbody></table></div><p class="report-note">${T('Thời gian batch trên CPU và độ trễ request API là hai cách đo khác nhau. Chi phí local chưa bao gồm hạ tầng; giá API theo cấu hình, không phải hóa đơn.','CPU batch latency and per-request API latency use different protocols. Local infrastructure costs are excluded; configured API prices are estimates, not invoices.')}</p>`)}${panel(T('F1 theo lớp','Per-class F1'),`<div class="table-wrap"><table><thead><tr><th>${T('LỚP','CLASS')}</th><th>PRECISION</th><th>RECALL</th><th>F1</th><th>N</th></tr></thead><tbody>${keys.map(k=>{const v=local.per_class?.[k];return `<tr><td>${badge(k)}</td><td>${pct(v?.precision)}</td><td>${pct(v?.recall)}</td><td>${pct(v?.['f1-score'])}</td><td>${num(v?.support)}</td></tr>`;}).join('')}</tbody></table></div>`)}${history.length?panel(T('Lịch sử chấm API','API benchmark history'),history.map(x=>`<button class="benchmark-row" data-action="evaluation:history" data-id="${x.id}"><span>#${x.id} · ${esc(x.report.model)} · ${x.report.sample_count} ${T('mẫu','samples')}</span><b>${pct(x.report.api?.macro_f1||x.report.gemini?.macro_f1)}</b></button>`).join('')):''}</div><div class="stack">${panel(T('Ma trận nhầm lẫn','Confusion matrix'),`<div class="table-wrap"><table class="confusion-table"><thead><tr><th>${T('Thật ↓ / Dự đoán →','True ↓ / Predicted →')}</th>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${(local.confusion_matrix||[]).map((row,i)=>`<tr><th>${esc(keys[i])}</th>${row.map((n,j)=>`<td class="${i===j?'matrix-correct':'matrix-error'}">${num(n)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,T('Hàng là nhãn thật, cột là dự đoán','Rows are truth; columns are predictions'))}${panel(T('Cấu hình tái lập','Reproducibility'),`<div class="summary-list"><div><span>Algorithm</span><b>${esc(m.algorithm)}</b></div><div><span>Seed</span><b>${r.seed}</b></div><div><span>Train</span><b>${num(r.counts?.train)}</b></div><div><span>Validation</span><b>${num(r.counts?.validation)}</b></div><div><span>Test</span><b>${num(r.counts?.test)}</b></div><div><span>${T('Tham số chọn','Selected parameter')}</span><b>${esc(JSON.stringify(r.selected_parameter||{C:r.selected_C}))}</b></div></div><p class="report-note">${esc(r.selection)}</p><p class="report-note">${esc(r.scope)}</p>`)}${panel(T('Baseline đa số','Majority-class baseline'),`<div class="summary-list"><div><span>Accuracy</span><b>${pct(r.majority_baseline?.accuracy)}</b></div><div><span>Macro-F1</span><b>${pct(r.majority_baseline?.macro_f1)}</b></div></div><p class="report-note">${T('Báo baseline để tránh kết luận chỉ từ accuracy khi dữ liệu mất cân bằng.','Report this baseline to avoid relying on accuracy for imbalanced data.')}</p>`)}</div></div>`;}
export async function action(name,el){if(name==='download'){download(JSON.stringify({models:state.workspace.models,benchmarks:state.workspace.benchmarks,generated_at:new Date().toISOString()},null,2),'annotaflow-evaluation.json');return;}if(name==='history'){selectedBenchmark=Number(el.dataset.id);const {repaint}=await import('../../core/events.js?v=9d97c650b6d2');await repaint();return;}if(name==='benchmark'){if(DEMO){nativeRequired();return;}modal(T('Chấm model và API trên cùng test','Evaluate model and API on the same test'),`<form data-submit="evaluation:benchmark">${select('model_id',T('Model tự train','Trained model'),state.workspace.models.map(m=>[m.id,m.name]),currentModel()?.id)}${select('connection_id',T('Kết nối API','API connection'),connections.map(c=>[c.id,c.name+' · '+c.model]),state.workspace.preferences.active_connection_id)}${select('limit',T('Số mẫu ghép cặp','Paired test samples'),[[50,'50'],[100,'100'],[1000,T('Tối đa 1.000','Up to 1,000')]],50)}<div class="info-banner">${icon('info',18)}<span>${T('Thao tác này gọi API thật và có thể phát sinh phí. Model và API được chấm trên đúng cùng ID; tập con 50/100 mẫu đầu không đại diện toàn bộ dữ liệu.','This sends real API requests and may incur charges. Both branches use the same IDs; a 50/100-row prefix is not representative of the entire dataset.')}</span></div>${formEnd(T('Chạy đánh giá','Run evaluation'))}</form>`,true);}}
export async function submit(name,f){const v=Object.fromEntries(new FormData(f));await api('benchmark',{project:state.workspace.project.id,model_id:Number(v.model_id),connection_id:Number(v.connection_id),limit:Number(v.limit)});closeModal();toast(T('Đã tạo tác vụ chấm ghép cặp. Xem tiến độ trong Dữ liệu → Tác vụ.','Paired benchmark job created. Track it in Data → Jobs.'));}
